// Standard Integer Sizes and Architecture (e.g., 64-bit system)
size_t s_int = sizeof(int);      // Typically 4 bytes (32 bits)
size_t s_long = sizeof(long);    // Varies (4 or 8 bytes)
size_t s_ll = sizeof(long long); // 8 bytes (64 bits)

size_t word_size = sizeof(void*); // Pointer size: 4 (32-bit) or 8 (64-bit)

// Two's Complement Negation
// To get -X: Invert all bits (~X) and add 1
int positive_x = 10;          // 0...01010
int negative_x = ~positive_x + 1; // 1...10110 (-10)

// Sign Extension during type promotion
char c = -5;
int i = c; // i = -5. Higher bits filled with sign bit (1).

// Integer Limits (N-bit signed)
// Range: [ -(2^(N-1)) , (2^(N-1)) - 1 ]
#define N_BITS (sizeof(int) * 8) // e.g., 32

const int INT_MAX_CALC = (1 << (N_BITS - 1)) - 1;
const int INT_MIN_CALC = -(1 << (N_BITS - 1));

// Unsigned Overflow (Defined wrap around)
unsigned char u = 255; // 1111 1111
u = u + 1;             // u becomes 0 (0000 0000)
u = u - 1;             // u becomes 255
// Signed Overflow (Undefined Behavior)
// char c = 127;
// c = c + 1; // Implementation dependent, usually -128.
